import com.anb.root.*;public class ServiceRegressionTest {static void check(boolean x,String n){if(!x)throw new AssertionError(n);}public static void main(String[] args){RecoveryService s=new RecoveryService();s.onCreate();s.onStartCommand(null,0,1);check(!RecoveryEngine.INSTANCE.lastAllow,"missing intent defaults to verify only");s.onStartCommand(null,0,2);check(s.foregroundStops==0&&s.selfStops==0&&RecoveryEngine.INSTANCE.starts==1,"duplicate start preserves active foreground owner");Runnable first=RecoveryEngine.INSTANCE.pending;RecoveryEngine.INSTANCE.pending=null;first.run();check(s.foregroundStops==1&&s.selfStops==1,"owner completes once");s.onStartCommand(new android.content.Intent(s,MainActivity.class).putExtra(RecoveryService.EXTRA_ALLOW_NEW_RECOVERY,true),0,3);check(RecoveryEngine.INSTANCE.lastAllow,"explicit restore carries permission");s.onDestroy();RecoveryEngine.INSTANCE.pending.run();check(s.foregroundStops==1,"destroyed service ignores late completion");RecoveryService denied=new RecoveryService();denied.failStart=true;int starts=RecoveryEngine.INSTANCE.starts;denied.onStartCommand(null,0,4);check(RecoveryEngine.INSTANCE.starts==starts&&RecoveryEngine.INSTANCE.serviceFailures==1&&denied.selfStops==1,"foreground failure cannot start recovery");System.out.println("PASS: actual service with framework substitutes: duplicate ownership, completion, verify-only default, explicit restore, destroyed callback");}}